INSERT INTO `disease` VALUES (1, '健康猪只', '猪气喘病,支原体肺炎,Mhp', NULL, '无呼吸道疾病的正常猪只', '呼吸平稳，无咳嗽，精神饱满', 'mycoplasma', 1, '2026-08-13 19:33:43');
INSERT INTO `disease` VALUES (2, '猪流行性感冒', '猪流感,SI,Swine Influenza', NULL, '流感病毒引起的急性呼吸道病', '鹅鸣样剧咳，突发高热，全群发病', 'influenza', 1, '2026-08-13 19:33:43');
INSERT INTO `disease` VALUES (3, '猪蓝耳病', '猪巴氏杆菌病,锁喉风,肿脖子瘟,Pasteurella multocida', NULL, '猪繁殖与呼吸综合征病毒引起', '高调湿咳，渐进性加重，腹式呼吸', 'pasteurella', 1, '2026-08-13 19:33:43');
INSERT INTO `disease` VALUES (4, '猪支原体肺炎', 'PRDC,多病原混合感染', NULL, '猪肺炎支原体引起的慢性呼吸道病', '慢性干咳，早晚加重，病程长', 'mixed', 1, '2026-08-13 19:33:43');
INSERT INTO `disease` VALUES (5, '猪传染性胸膜肺炎', 'APP,胸膜肺炎放线杆菌病', NULL, '胸膜肺炎放线杆菌引起', '急骤痛咳，湿咳，全身重症，高致死率', 'app', 13, '2026-08-13 19:33:43');
INSERT INTO `disease` VALUES (6, '猪繁殖与呼吸综合征', '蓝耳病,猪蓝耳病,PRRS,猪繁殖与呼吸障碍综合征,神秘猪病,HP-PRRS', '猪繁殖与呼吸综合征病毒（PRRSV）', '动脉炎病毒科RNA病毒，免疫抑制性强（\"免疫抑制之王\"），猪唯一易感；妊娠母猪和1月龄内仔猪最易感，哺乳仔猪死亡率可达80%以上；接触/气溶胶/精液/垂直四种传播途径；冬春高发', '繁殖障碍+呼吸道症状，\"三高一低\"（高体温/高发病率/高死亡率/低治愈率）：母猪发热40-42.5℃、妊娠后期流产早产死胎木乃伊胎、耳尖及躯干发绀；仔猪呼吸困难、耳尖发紫继而全耳蓝紫色、共济失调、僵猪比例大；育肥猪两耳发蓝、生长发育缓慢；剖检间质性肺炎\"橡皮肺\"', 'prrs', 13, '2026-08-13 19:33:43');
INSERT INTO `formula` VALUES (1, '迎甘组方', 2, '按500g饲料混饲', '连用5-7天', 'PPT三代技术实操验证方剂', 5, '2026-08-13 19:33:43');
INSERT INTO `formula` VALUES (2, '银翘散加减', 1, '按500g饲料混饲', '连用3-5天', '表证宣散，忌用于脾虚便溏', 3, '2026-08-13 19:33:43');
INSERT INTO `formula` VALUES (3, '生脉散加减', 3, '按500g饲料混饲', '连用7-10天', '扶正为主，外感未解者忌', 1, '2026-08-13 19:33:43');
INSERT INTO `formula` VALUES (4, '清肺止咳散加减', 4, '按500g饲料混饲', '连用5-7天', '痰热壅肺主方', 1, '2026-08-13 19:33:43');
INSERT INTO `formula` VALUES (5, '麻杏石甘汤', 2, '水煎，分2次灌服，或按比例混饲', '5天', '来源：《伤寒论》', 2, '2026-08-13 19:33:43');
INSERT INTO `formula` VALUES (6, '玉屏风散', 5, '共研细末，混饲给药', '7天', '来源：《世医得效方》', 8, '2026-08-13 19:33:43');
INSERT INTO `formula` VALUES (7, '二陈汤', 7, '水煎温服，加生姜7片乌梅1个', '连用3-5天', '燥湿化痰、理气和中', 9, '2026-08-13 19:33:43');
INSERT INTO `formula` VALUES (8, '荆防败毒散', 6, '共研细末，开水冲调，候温灌服，或混饲给药', '5天', '来源：《兽医手册》', 11, '2026-08-13 19:33:43');
INSERT INTO `formula` VALUES (9, '止嗽散', 6, '散剂6-9g/次，姜汤送服', '连用3-7天', '宣利肺气、疏风止咳，新久咳嗽皆宜', 10, '2026-08-13 19:33:43');
INSERT INTO `formula` VALUES (10, '清肺散', 2, '共研细末，混饲给药', '5天', '来源：兽医临床常用方', 12, '2026-08-13 19:33:43');
INSERT INTO `formula` VALUES (11, '麻杏石甘散（兽用）', 2, '猪30-60g/次拌料，每日1次', '连用5-7天', '清热宣肺平喘，肺热实喘', 13, '2026-08-13 19:33:43');
INSERT INTO `formula` VALUES (12, '银翘散（兽用）', 1, '猪50-80g拌料；颗粒100g拌200kg料', '连用5-7天', '辛凉解表、清热解毒，风热感冒', 3, '2026-08-13 19:33:43');
INSERT INTO `formula` VALUES (13, '双黄连口服液（兽用）', 1, '猪灌服10-15ml/次，或0.25ml/kg', '连用3-5天', '辛凉解表、清热解毒，流感/肺热咳喘', 13, '2026-08-13 19:33:43');
INSERT INTO `formula` VALUES (14, '板青颗粒（兽用）', 1, '猪混饲100g拌100-150kg料', '连用3-7天', '清热解毒、凉血，风热感冒/病毒病', 13, '2026-08-13 19:33:43');
INSERT INTO `formula` VALUES (15, '扶正解毒散', 1, '共研细末，混饲给药，每吨饲料添加1-2kg，连用7-10天', '10天', '来源：《中华人民共和国兽药典》', NULL, '2026-08-13 22:13:56');
INSERT INTO `formula` VALUES (17, '清瘟败毒散', 1, '共研细末，混饲或水煎灌服', '5天', '来源：《兽药规范》', NULL, '2026-08-13 22:13:56');
INSERT INTO `formula` VALUES (18, '三黄郁金汤', 1, '水煎灌服，每日1剂', '5天', '来源：《北方牧业》2005年17期', NULL, '2026-08-13 22:13:56');
INSERT INTO `formula` VALUES (20, '猪瘟治疗方（早期）', 1, '煎熬成汁，灌服', '5天', '来源：《中兽医验方》', NULL, '2026-08-13 22:13:56');
INSERT INTO `formula` VALUES (21, '猪圆环病毒病方', 1, '加水1000mL，煎熬3次取汁，去渣灌服，每日1次', '7天', '来源：《中兽医验方》', NULL, '2026-08-13 22:13:56');
INSERT INTO `formula` VALUES (22, '母猪保健方', 1, '共研细末，混饲给药，每1000市斤饲料添加', '7天', '来源：兽医临床验方', NULL, '2026-08-13 22:13:56');
