INSERT INTO `syndrome_mapping` VALUES (1, 38.5, 40.0, '湿咳、痰多、呼吸粗', '正常', '突发高烧+鹅鸣样剧咳+全群发病', 4, 2, '发热、咳嗽尖锐、流鼻涕、精神沉郁', 1, 1, '2026-08-13 19:33:43');
