INSERT INTO `syndrome_mapping` VALUES (3, 39.0, 41.0, '咳嗽、呼吸困难', '便秘', '久咳+消瘦+食欲不振', 6, 4, '消瘦、气短、久咳不止', 2, 1, '2026-08-13 19:33:43');
