-- ----------------------------
-- Table structure for acoustic_feature
-- ----------------------------
DROP TABLE IF EXISTS `acoustic_feature`;
CREATE TABLE `acoustic_feature`  (
  `feature_id` int(11) NOT NULL AUTO_INCREMENT,
  `diagnosis_id` bigint(20) UNSIGNED NOT NULL COMMENT '关联diagnosis_record.id',
  `feature_type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'MFCC/logFBank/时域/频域',
  `feature_dimension` int(11) NOT NULL COMMENT '特征维度',
  `feature_vector` json NOT NULL COMMENT '特征向量(JSON数组)',
