DROP TABLE IF EXISTS `add_rule`;
CREATE TABLE `add_rule`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT,
  `formula_id` bigint(20) UNSIGNED NOT NULL COMMENT '所属方剂',
  `condition_desc` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '加减条件',
