  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_formula`(`formula_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 12 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '随症加减规则表' ROW_FORMAT = Dynamic;

