-- ----------------------------
-- Table structure for agent_log
-- ----------------------------
DROP TABLE IF EXISTS `agent_log`;
CREATE TABLE `agent_log`  (
  `log_id` int(11) NOT NULL AUTO_INCREMENT,
  `run_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '本次运行ID(关联多个Agent)',
  `agent_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Agent名称: DxAgent/SxAgent/RxAgent/VxAgent',
  `diagnosis_id` bigint(20) UNSIGNED NULL DEFAULT NULL COMMENT '关联诊断记录ID',
  `input_data` json NULL COMMENT '输入数据',
  `output_data` json NULL COMMENT '输出数据',
  `prompt_text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '使用的Prompt',
  `tokens_used` int(11) NULL DEFAULT NULL COMMENT 'Token消耗',
  `response_time_ms` int(11) NULL DEFAULT NULL COMMENT '响应耗时(毫秒)',
  `status` enum('成功','失败','超时') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '成功',
  `error_message` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '错误信息',
  `run_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`log_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'Agent运行日志表' ROW_FORMAT = Dynamic;

