  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_house_time`(`pig_house`, `created_at`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 569 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '辨病记录' ROW_FORMAT = Dynamic;

