  `alias` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '别名，逗号分隔（俗名/缩写/曾用名），如：蓝耳病,PRRS',
  `pathogen` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '病原体',
