-- ----------------------------
-- Table structure for farmer_guidance
-- ----------------------------
DROP TABLE IF EXISTS `farmer_guidance`;
CREATE TABLE `farmer_guidance`  (
  `guidance_id` int(11) NOT NULL AUTO_INCREMENT,
  `group_id` int(11) NOT NULL COMMENT '猪群ID',
  `feedback_id` int(11) NULL DEFAULT NULL COMMENT '基于的反馈ID（关联treatment_feedback）',
  `prescription_id` bigint(20) UNSIGNED NULL DEFAULT NULL COMMENT '关联处方ID（关联prescription_record）',
  `guidance_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  `guidance_type` enum('初诊建议','增减用量','换方','停药','加强护理','紧急处理') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '指导类型',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '指导正文(自然语言)',
  `suggested_adjustments` json NULL COMMENT '建议调整: [{\"herb_name\":\"麻黄\",\"change\":\"+3g\",\"reason\":\"...\"}]',
  `urgency_level` enum('普通','紧急') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '普通',
  `is_executed` tinyint(1) NULL DEFAULT 0 COMMENT '农户是否已执行',
  `executed_time` datetime NULL DEFAULT NULL COMMENT '执行时间',
  `executed_result` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '执行结果描述',
  `generated_by` enum('AI','兽医','系统') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'AI',
  `agent_version` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '生成Agent版本',
  PRIMARY KEY (`guidance_id`) USING BTREE,
  INDEX `group_id`(`group_id`) USING BTREE,
  CONSTRAINT `farmer_guidance_ibfk_1` FOREIGN KEY (`group_id`) REFERENCES `pig_groups` (`group_id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '农户指导建议表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of farmer_guidance
-- ----------------------------

