-- ----------------------------
-- Records of pigs
-- ----------------------------

-- ----------------------------
-- Table structure for prescription_record
-- ----------------------------
DROP TABLE IF EXISTS `prescription_record`;
CREATE TABLE `prescription_record`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT,
  `diagnosis_id` bigint(20) UNSIGNED NULL DEFAULT NULL COMMENT '关联辨病记录',
  `syndrome_id` bigint(20) UNSIGNED NULL DEFAULT NULL COMMENT '辨证结果-证候',
  `formula_id` bigint(20) UNSIGNED NULL DEFAULT NULL COMMENT '基础方剂',
  `herbs_json` json NULL COMMENT '组方明细[{name,dosage_g,role}]',
  `usage_method` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '用法',
  `course` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '疗程',
  `safety_approved` tinyint(1) NULL DEFAULT 0 COMMENT '校验是否通过',
  `safety_report` json NULL COMMENT '校验报告',
  `llm_raw` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT 'LLM原始输出(审计用)',
  `references_json` json NULL COMMENT '引用出处列表',
  `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_diagnosis`(`diagnosis_id`) USING BTREE,
  INDEX `idx_syndrome`(`syndrome_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '处方记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of prescription_record
-- ----------------------------

-- ----------------------------
-- Table structure for syndrome
-- ----------------------------
DROP TABLE IF EXISTS `syndrome`;
CREATE TABLE `syndrome`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT,
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '证候名',
  `stage` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '中医分期',
  `description` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '证候描述',
  `principle` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '治则治法',
  `reference_id` bigint(20) UNSIGNED NULL DEFAULT NULL,
  `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `name`(`name`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '证候表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of syndrome
-- ----------------------------

-- ----------------------------
-- Table structure for syndrome_mapping
-- ----------------------------
DROP TABLE IF EXISTS `syndrome_mapping`;
CREATE TABLE `syndrome_mapping`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT,
  `temperature_min` decimal(4, 1) NULL DEFAULT NULL COMMENT '体温下限(℃)，NULL=不限',
  `temperature_max` decimal(4, 1) NULL DEFAULT NULL COMMENT '体温上限(℃)，NULL=不限',
  `cough_type` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '咳喘表现关键词',
  `excretion` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '排泄物观察',
  `other_signs` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '其他体征：精神、采食、呼吸等',
  `syndrome_id` bigint(20) UNSIGNED NOT NULL COMMENT '命中证候',
  `disease_id` bigint(20) UNSIGNED NULL DEFAULT NULL COMMENT '关联疾病(可空)',
  `evidence` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '鉴别依据',
  `weight` tinyint(3) UNSIGNED NULL DEFAULT 5 COMMENT '权重1-10',
  `reference_id` bigint(20) UNSIGNED NULL DEFAULT NULL,
  `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_syndrome`(`syndrome_id`) USING BTREE,
  INDEX `idx_disease`(`disease_id`) USING BTREE,
  INDEX `idx_temp`(`temperature_min`, `temperature_max`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 12 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '辨证库：多维体征→证候映射' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of syndrome_mapping
-- ----------------------------

-- ----------------------------
-- Table structure for system_config
-- ----------------------------
DROP TABLE IF EXISTS `system_config`;
CREATE TABLE `system_config`  (
  `config_id` int(11) NOT NULL AUTO_INCREMENT,
  `config_key` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '配置键',
  `config_value` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '配置值',
  `config_group` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '配置分组',
  `description` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '说明',
  `updated_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`config_id`) USING BTREE,
  UNIQUE INDEX `config_key`(`config_key`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 8 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '系统配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of system_config
-- ----------------------------

-- ----------------------------
-- Table structure for training_dataset
-- ----------------------------
DROP TABLE IF EXISTS `training_dataset`;
CREATE TABLE `training_dataset`  (
  `dataset_id` int(11) NOT NULL AUTO_INCREMENT,
  `dataset_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '数据集名称',
  `dataset_type` enum('诊断','辨证','组方','综合') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '数据集类型',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '描述',
  `record_ids` json NULL COMMENT '包含的diagnosis_record ID列表',
  `total_samples` int(11) NULL DEFAULT NULL COMMENT '总样本数',
  `label_distribution` json NULL COMMENT '标签分布',
  `created_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  `created_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  PRIMARY KEY (`dataset_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '训练数据集管理表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of training_dataset
-- ----------------------------

-- ----------------------------
-- Table structure for treatment_feedback
-- ----------------------------
DROP TABLE IF EXISTS `treatment_feedback`;
CREATE TABLE `treatment_feedback`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT,
  `prescription_id` bigint(20) UNSIGNED NOT NULL,
  `day_after` tinyint(3) UNSIGNED NULL DEFAULT NULL COMMENT '用药第N天',
  `cough_freq_change` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '咳嗽频率变化',
  `temp_change` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '体温变化',
  `mental_change` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '精神状态变化',
  `outcome` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '结局：治愈/好转/无效/恶化',
  `adjustment` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '方案调整',
  `effective_score` decimal(3, 2) NULL DEFAULT NULL COMMENT '疗效评分0-1',
  `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_prescription`(`prescription_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '疗效反馈表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of treatment_feedback
-- ----------------------------

-- ----------------------------
-- Table structure for user_group
-- ----------------------------
DROP TABLE IF EXISTS `user_group`;
CREATE TABLE `user_group`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `group_id` int(11) NOT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_user_group`(`user_id`, `group_id`) USING BTREE,
  INDEX `group_id`(`group_id`) USING BTREE,
  CONSTRAINT `user_group_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `user_group_ibfk_2` FOREIGN KEY (`group_id`) REFERENCES `pig_groups` (`group_id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '用户-猪群关联表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of user_group
-- ----------------------------

-- ----------------------------
-- Table structure for users
-- ----------------------------
DROP TABLE IF EXISTS `users`;
CREATE TABLE `users`  (
  `user_id` int(11) NOT NULL AUTO_INCREMENT,
  `username` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '用户名',
  `password_hash` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '密码哈希',
  `role` enum('farmer','veterinarian','admin','researcher') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'farmer' COMMENT '角色',
  `real_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '真实姓名',
  `phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '手机号',
  `farm_id` int(11) NULL DEFAULT NULL COMMENT '关联养殖场ID',
  `created_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  `last_login` datetime NULL DEFAULT NULL COMMENT '最后登录时间',
  PRIMARY KEY (`user_id`) USING BTREE,
  UNIQUE INDEX `username`(`username`) USING BTREE,
  INDEX `farm_id`(`farm_id`) USING BTREE,
  CONSTRAINT `users_ibfk_1` FOREIGN KEY (`farm_id`) REFERENCES `pig_farms` (`farm_id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '用户表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of users
-- ----------------------------

SET FOREIGN_KEY_CHECKS = 1;
